cd /home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring; python3 - <<'EOF'
p='src/main/frontend/src/app/features/people/people.ts'
s=open(p).read()
old='''  /** The person's patrons' due-totals added up, skipping the n/a ones; 0.00 with no patrons. */
  protected backingOf(person: Person): string {
    return sumDues(this.patronsListOf(person).map((p) => this.dueTotalOf(p)));
  }'''
new='''  /**
   * The person's patrons' settled figures added up: each patron's SETTLED claims dated within the 90 days up to and
   * including the sheet's today, each at its frozen figure; 0.00 with none.
   */
  protected backingOf(person: Person): string {
    const today = this.session.today();
    if (today === null) return '0.00';
    const since = plusDays(today, -89);
    return sumDues(
      this.patronsListOf(person).flatMap((p) =>
        this.claimsOf(p.id)
          .filter((c) => c.status === 'SETTLED' && since <= c.date && c.date <= today)
          .map((c) => claimDue(c, this.rates(), p.grades, this.session)),
      ),
    );
  }'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF
sed -i 's/^-- once. A person.s backing is their patrons. due-totals added up.$/&/' src/main/resources/db/migration/V22__person_patron.sql
bin/e2e 2>&1 | tail -30

